#include <bits/stdc++.h>
using namespace std;
using ll = long long ;
#define fast  ios::sync_with_stdio(false); cin.tie(nullptr);
#define pb push_back

void solve(){
    int n; cin >> n;
    int m = 3 * n;
    vector<ll>a(m);
    for(auto &x : a) cin >> x;
    
    sort(a.rbegin(),a.rend());
    
    vector<ll> p(m + 1,0);
    for(int i=0; i< m; i++){
        p[i + 1] = p[i] + a[i];
    }
    ll ans = INT_MIN;
    
    for(int i = 0; i<=n; i++){
        int low = 0, high = n-i;
        
        while(high-low >2){
            int k1 = low + (high-low)/3;
            int k2 = high - (high - low)/3;
            ll s1 = p[i + 2 * k1] + 3LL * p[3 *  n-2 * i - k1];
            ll s2 = p[i + 2 * k2] + 3LL * p[3 *  n-2 * i - k2];
        if(s1 < s2) low = k1;
        else high = k2;
        }
        
        for( int f = low; f<=high; f++){
            ll ans1 = 2LL * p[i] + p[i + 2 *f] + 3LL*p[3 *n-2 *i-f];
            if(ans1 > ans){
                ans = ans1;
            }
        }
    }
    cout << ans << "\n";
}

int main() {
	fast;
	int t; cin >> t;
	while(t--) solve();
	return 0;
	// your code goes here

}
